module basic {
  namespace "urn:vibe-ports:yang:conformance:basic";
  prefix b;

  description
    "Hand-written seed fixture module for the yang oracle corpus.";

  container sys {
    config true;
    status current;
    leaf mtu {
      type uint16 {
        range "68..9000";
      }
      config true;
      status current;
    }
    list iface {
      key "name";
      config true;
      min-elements 0;
      max-elements 4294967295;
      ordered-by system;
      status current;
      leaf name {
        type string;
        config true;
        status current;
      }
      leaf type {
        type string;
        config true;
        status current;
      }
    }
    leaf primary {
      type leafref {
        path "../iface/name";
        require-instance true;
        type string;
      }
      config true;
      status current;
    }
    leaf jumbo-frames {
      when "../mtu > 1500";
      type boolean;
      config true;
      status current;
    }
    leaf min {
      type uint8;
      config true;
      status current;
    }
    leaf max {
      type uint8;
      must ". >= ../min" {
        error-message
          "max must not be below min";
        error-app-tag "max-below-min";
      }
      config true;
      status current;
    }
    container user {
      presence "true";
      config true;
      status current;
      leaf name {
        type string;
        config true;
        mandatory true;
        status current;
      }
      leaf shell {
        type string;
        default "/bin/sh";
        config true;
        status current;
      }
    }
  }
}
